package com.yokuli.anchorwatch.data.vessel

import android.os.SystemClock
import com.yokuli.anchorwatch.data.NavigationRepository
import com.yokuli.anchorwatch.data.condition.LiveDepthRepository
import com.yokuli.anchorwatch.data.condition.LiveWindRepository
import com.yokuli.anchorwatch.data.nmea.NmeaFieldObservation
import com.yokuli.anchorwatch.data.nmea.NmeaFieldRepository
import com.yokuli.anchorwatch.data.nmea.NmeaFieldSemantic
import com.yokuli.anchorwatch.domain.model.HeadingSource
import com.yokuli.anchorwatch.domain.sonar.DepthReference
import com.yokuli.anchorwatch.domain.vessel.*
import com.yokuli.anchorwatch.location.PhoneHeadingRepository
import com.yokuli.anchorwatch.location.vessel.PhonePressureRepository
import com.yokuli.anchorwatch.location.vessel.PhoneVesselAttitudeRepository
import javax.inject.Inject
import javax.inject.Singleton
import kotlin.math.abs
import kotlin.math.atan2
import kotlin.math.cos
import kotlin.math.hypot
import kotlin.math.sin
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

/** Unified instrument/presentation truth. It never feeds Anchor safety. */
@Singleton
class VesselDataHub @Inject constructor(navigation:NavigationRepository,depth:LiveDepthRepository,wind:LiveWindRepository,phoneHeading:PhoneHeadingRepository,positions:VesselPositionRepository,settings:VesselSettingsRepository,outputSettings:OutputSettingsRepository,attitude:PhoneVesselAttitudeRepository,pressure:PhonePressureRepository,nmeaFields:NmeaFieldRepository){
    private val scope=CoroutineScope(SupervisorJob()+Dispatchers.Default);private val _snapshot=MutableStateFlow(VesselDataSnapshot());val snapshot=_snapshot.asStateFlow()
    private var boatPosition=VesselObservation<VesselPosition>();private var phonePosition=VesselObservation<VesselPosition>();private var sog=VesselObservation<Double>();private var cog=VesselObservation<Double>();private var speedThroughWater=VesselObservation<Double>();private var boatHeading=VesselObservation<Double>();private var magneticHeading=VesselObservation<Double>();private var phoneHeadingValue=VesselObservation<Double>();private var depthValue=VesselObservation<Double>();private var trueWindSpeed=VesselObservation<Double>();private var trueWindDirection=VesselObservation<Double>();private var trueWindAngle=VesselObservation<Double>();private var apparentWindSpeed=VesselObservation<Double>();private var apparentWindAngle=VesselObservation<Double>();private var attitudeValue=VesselObservation<VesselAttitude>();private var motionValue=VesselObservation<VesselMotion>();private var pressureValue=VesselObservation<Double>();private var rateOfTurn=VesselObservation<Double>();private var rudderAngle=VesselObservation<Double>();private var waterTemperature=VesselObservation<Double>();private var airTemperature=VesselObservation<Double>();private var currentSet=VesselObservation<Double>();private var currentDrift=VesselObservation<Double>();private var crossTrackError=VesselObservation<Double>();private var waypointBearing=VesselObservation<Double>();private var waypointDistance=VesselObservation<Double>();private var destinationWaypoint=VesselObservation<String>();private var totalLog=VesselObservation<Double>();private var tripLog=VesselObservation<Double>();private val motionAnalyzer=VesselMotionAnalyzer()
    private val positionSelector=VesselAutoSourceSelector<VesselPosition>();private val headingSelector=VesselAutoSourceSelector<Double>();private val pressureTrends=PressureTrendEstimator()
    @Volatile private var positionPreference=VesselSourcePreference.AUTO;@Volatile private var headingPreference=VesselSourcePreference.AUTO
    @Volatile private var phonePositionOutputEnabled=false
    @Volatile private var vesselDraftMeters=0.0
    @Volatile private var depthReference:DepthReference?=null
    init{
        scope.launch{positions.boat.collect{boatPosition=it}};scope.launch{positions.phone.collect{phonePosition=it}}
        scope.launch{navigation.transportDiagnostics.map{it.connectionGeneration}.distinctUntilChanged().drop(1).collect{clearBoatGeneration()}}
        scope.launch{navigation.instruments.collect{value->value.sogOrNull()?.let{sog=it};value.cogOrNull()?.let{cog=it};value.stwOrNull()?.let{speedThroughWater=it};value.trueHeadingOrNull()?.let{boatHeading=it};value.magneticHeadingOrNull()?.let{magneticHeading=it}}}
        scope.launch{navigation.fix.filterNotNull().collect{fix->val source=VesselDataSource.BOAT_NMEA;fix.sogKnots?.let{sog=observation(it,source,fix.sogReceivedElapsedRealtime?:fix.receivedElapsedRealtime,fix.timestampUtcMillis,"NMEA SOG")};fix.cogTrueDegrees?.let{cog=observation(it,source,fix.cogReceivedElapsedRealtime?:fix.receivedElapsedRealtime,fix.timestampUtcMillis,"NMEA COG")};fix.speedThroughWaterKnots?.let{speedThroughWater=observation(it,source,fix.speedThroughWaterReceivedElapsedRealtime?:fix.receivedElapsedRealtime,fix.timestampUtcMillis,"VHW")};if(fix.headingSource==HeadingSource.NMEA_PHYSICAL)fix.headingTrueDegrees?.let{boatHeading=observation(it,source,fix.headingReceivedElapsedRealtime?:fix.receivedElapsedRealtime,fix.timestampUtcMillis,"HDT/HDG/VHW")};fix.headingMagneticDegrees?.let{magneticHeading=observation(it,source,fix.headingMagneticReceivedElapsedRealtime?:fix.receivedElapsedRealtime,fix.timestampUtcMillis,"HDM/HDG/VHW")}}}
        scope.launch{depth.state.collect{value->depthReference=value.reference;value.depthMeters?.let{meters->depthValue=observation(meters,if(value.isDemo)VesselDataSource.DEMO else VesselDataSource.BOAT_NMEA,value.receivedElapsedRealtime,System.currentTimeMillis(),"${value.sentenceType?.name?:"DEPTH"}:${value.reference?.name?:"UNKNOWN"}")}}}
        scope.launch{wind.state.collect{value->value.trueSpeed?.let{trueWindSpeed=observation(it.value,VesselDataSource.BOAT_NMEA,it.receivedElapsedRealtime,null,"NMEA true wind")};value.trueDirection?.let{trueWindDirection=observation(it.value,VesselDataSource.BOAT_NMEA,it.receivedElapsedRealtime,null,value.trueDirectionSource?.name)};value.trueAngle?.let{trueWindAngle=observation(it.value,VesselDataSource.BOAT_NMEA,it.receivedElapsedRealtime,null,"NMEA true angle")};value.apparentSpeed?.let{apparentWindSpeed=observation(it.value,VesselDataSource.BOAT_NMEA,it.receivedElapsedRealtime,null,"NMEA apparent wind")};value.apparentAngle?.let{apparentWindAngle=observation(it.value,VesselDataSource.BOAT_NMEA,it.receivedElapsedRealtime,null,"NMEA apparent angle")}}}
        scope.launch{phoneHeading.sample.collect{sample->sample.trueHeadingDegrees?.let{value->phoneHeadingValue=observation(value,VesselDataSource.PHONE_MAGNETOMETER,sample.receivedElapsedRealtime,null,"Integrity-gated phone heading",if(sample.quality.name=="STABLE")VesselDataQuality.GOOD else VesselDataQuality.DEGRADED)}}}
        scope.launch{attitude.sample.collect{sample->val value=sample.attitude;if(value!=null&&sample.receivedElapsedRealtime!=null){val quality=if(sample.mountSuspect)VesselDataQuality.DEGRADED else VesselDataQuality.GOOD;attitudeValue=observation(value,VesselDataSource.PHONE_IMU,sample.receivedElapsedRealtime,null,if(sample.mountSuspect)"PHONE_MOVED_OR_MOUNT_SUSPECT" else "calibrated vessel frame",quality);if(!sample.mountSuspect){val motion=motionAnalyzer.add(VesselMotionPoint(sample.receivedElapsedRealtime,value.heelDegrees,value.pitchDegrees,value.rollRateDegreesPerSecond,value.pitchRateDegreesPerSecond,sample.dynamicAccelerationG));motionValue=observation(motion,VesselDataSource.DERIVED,sample.receivedElapsedRealtime,null,VesselMotionAnalyzer.ALGORITHM_VERSION)}}}}
        scope.launch{pressure.sample.collect{sample->sample.pressureHpa?.let{value->sample.receivedElapsedRealtime?.let{pressureTrends.add(it,value)};pressureValue=observation(value,VesselDataSource.PHONE_BAROMETER,sample.receivedElapsedRealtime,null,"TYPE_PRESSURE")}}}
        scope.launch{nmeaFields.fields.collect{fields->
            fun numeric(semantic:NmeaFieldSemantic)=fields.filter{it.key.semantic==semantic&&it.value!=null}.maxByOrNull{it.receivedElapsedRealtime}
            fun textual(semantic:NmeaFieldSemantic)=fields.filter{it.key.semantic==semantic&&!it.text.isNullOrBlank()}.maxByOrNull{it.receivedElapsedRealtime}
            fun update(current:VesselObservation<Double>,semantic:NmeaFieldSemantic)=numeric(semantic)?.let{fieldObservation(it,it.value!!)}?:current
            rateOfTurn=update(rateOfTurn,NmeaFieldSemantic.ROT);rudderAngle=update(rudderAngle,NmeaFieldSemantic.RUDDER_ANGLE);waterTemperature=update(waterTemperature,NmeaFieldSemantic.WATER_TEMPERATURE);airTemperature=update(airTemperature,NmeaFieldSemantic.AIR_TEMPERATURE)
            currentSet=update(currentSet,NmeaFieldSemantic.CURRENT_SET_TRUE);currentDrift=update(currentDrift,NmeaFieldSemantic.CURRENT_DRIFT);crossTrackError=update(crossTrackError,NmeaFieldSemantic.CROSS_TRACK_ERROR);waypointBearing=update(waypointBearing,NmeaFieldSemantic.BEARING_TO_WAYPOINT);waypointDistance=update(waypointDistance,NmeaFieldSemantic.DISTANCE_TO_WAYPOINT);totalLog=update(totalLog,NmeaFieldSemantic.TOTAL_LOG);tripLog=update(tripLog,NmeaFieldSemantic.TRIP_LOG)
            numeric(NmeaFieldSemantic.AIR_PRESSURE)?.let{pressureValue=fieldObservation(it,it.value!!)}
            numeric(NmeaFieldSemantic.APPARENT_WIND_ANGLE)?.let{apparentWindAngle=fieldObservation(it,it.value!!)};numeric(NmeaFieldSemantic.APPARENT_WIND_SPEED)?.let{apparentWindSpeed=fieldObservation(it,it.value!!)}
            numeric(NmeaFieldSemantic.TRUE_WIND_ANGLE)?.let{trueWindAngle=fieldObservation(it,it.value!!)};numeric(NmeaFieldSemantic.TRUE_WIND_SPEED)?.let{trueWindSpeed=fieldObservation(it,it.value!!)}
            numeric(NmeaFieldSemantic.TRUE_WIND_DIRECTION)?.let{trueWindDirection=fieldObservation(it,it.value!!)}
            textual(NmeaFieldSemantic.DESTINATION_WAYPOINT)?.let{destinationWaypoint=fieldObservation(it,it.text!!)}
        }}
        scope.launch{settings.settings.collect{value->positionPreference=value.positionPreference;headingPreference=value.headingPreference;vesselDraftMeters=value.draftMeters?:0.0}}
        scope.launch{outputSettings.settings.collect{phonePositionOutputEnabled=it.phonePositionEnabled}}
        scope.launch{while(isActive){publish(SystemClock.elapsedRealtime());delay(250)}}
    }
    @Synchronized private fun publish(now:Long){
        val classifiedBoatPosition=classify(boatPosition,now,3_000,30_000).let{if(phonePositionOutputEnabled)it.copy(value=null,freshness=VesselDataFreshness.UNAVAILABLE,provenance="BLOCKED_BY_PHONE_POSITION_OUTPUT")else it}
        val selectedPosition=positionSelector.select(positionPreference,classifiedBoatPosition,classify(phonePosition,now,3_000,10_000),now);val selectedHeading=headingSelector.select(headingPreference,classify(boatHeading,now,5_000,30_000),classify(phoneHeadingValue,now,1_500,5_000),now);val freshCog=classify(cog,now,5_000,30_000)
        val headingCog=if(selectedHeading.value!=null&&freshCog.value!=null){val difference=abs(((selectedHeading.value-freshCog.value+540.0)%360.0)-180.0);VesselObservation(difference,VesselDataSource.DERIVED,receivedElapsedRealtime=now,quality=if(selectedHeading.freshness==VesselDataFreshness.FRESH&&freshCog.freshness==VesselDataFreshness.FRESH)VesselDataQuality.GOOD else VesselDataQuality.DEGRADED,freshness=if(selectedHeading.freshness==VesselDataFreshness.FRESH&&freshCog.freshness==VesselDataFreshness.FRESH)VesselDataFreshness.FRESH else VesselDataFreshness.HELD,provenance="heading minus COG")}else VesselObservation()
        val classifiedDepth=classify(depthValue,now,3_000,60_000);val classifiedPressure=classify(pressureValue,now,10_000,10*60_000)
        val ukcValue=UkcCompatibilityPolicy.calculate(classifiedDepth.value,depthReference,vesselDraftMeters)
        val ukc=if(ukcValue!=null)classifiedDepth.copy(value=ukcValue,source=VesselDataSource.DERIVED,provenance="surface-referenced depth minus configured vessel draft")else VesselObservation()
        fun pressureTrend(window:Long):VesselObservation<Double>{val value=pressureTrends.trend(now,window)?:return VesselObservation();return VesselObservation(value.changeHpa,VesselDataSource.DERIVED,receivedElapsedRealtime=classifiedPressure.receivedElapsedRealtime,quality=classifiedPressure.quality,freshness=classifiedPressure.freshness,provenance="linear pressure trend; coverage=${value.coverage}")}
        val freshSog=classify(sog,now,5_000,30_000);val freshStw=classify(speedThroughWater,now,5_000,60_000);val freshTwa=classify(trueWindAngle,now,5_000,60_000);val freshWaypointBearing=classify(waypointBearing,now,10_000,60_000)
        val vmg=projectedSpeed(freshStw.value?:freshSog.value,freshTwa.value,now,"speed × cos(TWA)")
        val vmc=projectedSpeed(freshSog.value,freshCog.value?.let{course->freshWaypointBearing.value?.let{bearing->signedAngle(course-bearing)}},now,"SOG × cos(COG-bearing)")
        val estimatedCurrent=estimateCurrent(freshSog.value,freshCog.value,freshStw.value,selectedHeading.value,now)
        _snapshot.value=VesselDataSnapshot(position=selectedPosition,sogKnots=freshSog,cogTrueDegrees=freshCog,headingTrueDegrees=selectedHeading,headingMagneticDegrees=classify(magneticHeading,now,5_000,30_000),depthMeters=classifiedDepth,speedThroughWaterKnots=freshStw,trueWind=VesselWindObservation(classify(trueWindSpeed,now,5_000,60_000),classify(trueWindDirection,now,5_000,60_000),freshTwa),apparentWind=VesselWindObservation(classify(apparentWindSpeed,now,5_000,60_000),VesselObservation(),classify(apparentWindAngle,now,5_000,60_000)),attitude=classify(attitudeValue,now,1_000,5_000),motion=classify(motionValue,now,2_000,10_000),pressureHpa=classifiedPressure,rateOfTurnDegreesPerMinute=classify(rateOfTurn,now,5_000,30_000),rudderAngleDegrees=classify(rudderAngle,now,5_000,30_000),waterTemperatureCelsius=classify(waterTemperature,now,30_000,5*60_000),airTemperatureCelsius=classify(airTemperature,now,30_000,5*60_000),currentSetTrueDegrees=classify(currentSet,now,10_000,60_000),currentDriftKnots=classify(currentDrift,now,10_000,60_000),crossTrackErrorNauticalMiles=classify(crossTrackError,now,10_000,60_000),waypointBearingTrueDegrees=freshWaypointBearing,waypointDistanceNauticalMiles=classify(waypointDistance,now,10_000,60_000),destinationWaypoint=classify(destinationWaypoint,now,10_000,60_000),totalLogNauticalMiles=classify(totalLog,now,30_000,5*60_000),tripLogNauticalMiles=classify(tripLog,now,30_000,5*60_000),derived=VesselDerivedSnapshot(underKeelClearanceMeters=ukc,headingCogDifferenceDegrees=headingCog,pressureTrend1hHpa=pressureTrend(60*60_000L),pressureTrend3hHpa=pressureTrend(3*60*60_000L),pressureTrend6hHpa=pressureTrend(6*60*60_000L),vmgToWindKnots=vmg,vmcToWaypointKnots=vmc,estimatedCurrentSetTrueDegrees=estimatedCurrent?.first?:VesselObservation(),estimatedCurrentDriftKnots=estimatedCurrent?.second?:VesselObservation()),generatedElapsedRealtime=now)
    }
    @Synchronized private fun clearBoatGeneration(){boatPosition=VesselObservation();sog=VesselObservation();cog=VesselObservation();speedThroughWater=VesselObservation();boatHeading=VesselObservation();magneticHeading=VesselObservation();depthValue=VesselObservation();depthReference=null;trueWindSpeed=VesselObservation();trueWindDirection=VesselObservation();trueWindAngle=VesselObservation();apparentWindSpeed=VesselObservation();apparentWindAngle=VesselObservation();rateOfTurn=VesselObservation();rudderAngle=VesselObservation();waterTemperature=VesselObservation();airTemperature=VesselObservation();currentSet=VesselObservation();currentDrift=VesselObservation();crossTrackError=VesselObservation();waypointBearing=VesselObservation();waypointDistance=VesselObservation();destinationWaypoint=VesselObservation();totalLog=VesselObservation();tripLog=VesselObservation();positionSelector.reset();headingSelector.reset()}
    private fun <T> classify(value:VesselObservation<T>,now:Long,fresh:Long,held:Long)=VesselFreshnessPolicy.classify(value,now,fresh,held)
    private fun <T> observation(value:T,source:VesselDataSource,received:Long?,observed:Long?,provenance:String?,quality:VesselDataQuality=VesselDataQuality.GOOD)=VesselObservation(value,source,observed,received,quality,VesselDataFreshness.FRESH,provenance)
    private fun <T> fieldObservation(field:NmeaFieldObservation,value:T)=observation(value,VesselDataSource.BOAT_NMEA,field.receivedElapsedRealtime,null,"${field.key.sentenceType}:${field.key.fieldIndex}${field.key.transducerName?.let{":$it"}.orEmpty()}")
    private fun projectedSpeed(speed:Double?,angle:Double?,now:Long,provenance:String):VesselObservation<Double>{if(speed==null||angle==null)return VesselObservation();return VesselObservation(speed*cos(Math.toRadians(angle)),VesselDataSource.DERIVED,receivedElapsedRealtime=now,quality=VesselDataQuality.GOOD,freshness=VesselDataFreshness.FRESH,provenance=provenance)}
    private fun signedAngle(value:Double)=((value+540.0)%360.0)-180.0
    private fun estimateCurrent(sog:Double?,cog:Double?,stw:Double?,heading:Double?,now:Long):Pair<VesselObservation<Double>,VesselObservation<Double>>?{if(sog==null||cog==null||stw==null||heading==null)return null;val groundEast=sog*sin(Math.toRadians(cog));val groundNorth=sog*cos(Math.toRadians(cog));val waterEast=stw*sin(Math.toRadians(heading));val waterNorth=stw*cos(Math.toRadians(heading));val east=groundEast-waterEast;val north=groundNorth-waterNorth;val drift=hypot(east,north);val set=(Math.toDegrees(atan2(east,north))+360.0)%360.0;val base=VesselObservation(set,VesselDataSource.DERIVED,receivedElapsedRealtime=now,quality=VesselDataQuality.DEGRADED,freshness=VesselDataFreshness.FRESH,provenance="ground velocity minus through-water velocity");return base to base.copy(value=drift)}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.sogOrNull()=speedOverGroundKnots?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"NMEA SOG")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.cogOrNull()=courseOverGroundTrue?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"NMEA COG")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.stwOrNull()=speedThroughWaterKnots?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"VHW")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.trueHeadingOrNull()=headingTrue?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"HDT/HDG/VHW")}
    private fun com.yokuli.anchorwatch.data.NmeaInstrumentState.magneticHeadingOrNull()=headingMagnetic?.let{observation(it.first,VesselDataSource.BOAT_NMEA,it.second,null,"HDM/HDG/VHW")}
}
